/*
 * STM32F746G-DISCO Onboard LCD Demo
 * Draws shapes, text, and colours on the 4.3" 480x272 TFT.
 * No external wiring needed — uses the built-in LCD.
 * Uses Adafruit_GFX / Adafruit_ILI9341 API.
 */

#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>

// STM32 F746 onboard LCD — CS/DC/RST are directly wired to the FMC
// In ArduSim, the library writes directly to the board's LCD.
Adafruit_ILI9341 tft(10, 9, 8); // CS, DC, RST (dummy pins — onboard)

void setup() {
  Serial.begin(115200);
  Serial.println("STM32F746G-DISCO LCD demo");

  tft.begin();
  tft.setRotation(1); // landscape

  // Fill screen with dark blue
  tft.fillScreen(ILI9341_NAVY);

  // Draw title
  tft.setTextColor(ILI9341_YELLOW);
  tft.setTextSize(3);
  tft.setCursor(20, 10);
  tft.println("STM32F746G-DISCO");

  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(2);
  tft.setCursor(20, 50);
  tft.println("Onboard 4.3 inch TFT LCD");
  tft.println("480 x 272 pixels");

  // Draw coloured rectangles
  tft.fillRect(20, 100, 120, 60, ILI9341_RED);
  tft.fillRect(160, 100, 120, 60, ILI9341_GREEN);
  tft.fillRect(300, 100, 120, 60, ILI9341_BLUE);

  // Labels on rectangles
  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(2);
  tft.setCursor(50, 120);  tft.print("RED");
  tft.setCursor(190, 120); tft.print("GREEN");
  tft.setCursor(325, 120); tft.print("BLUE");

  // Draw circles
  tft.drawCircle(100, 220, 30, ILI9341_CYAN);
  tft.fillCircle(240, 220, 30, ILI9341_MAGENTA);
  tft.drawRoundRect(340, 190, 80, 60, 10, ILI9341_ORANGE);

  // Draw diagonal lines
  for (int i = 0; i < 4; i++) {
    tft.drawLine(0, 260 - i * 10, 480, 270 - i * 5, ILI9341_WHITE);
  }

  Serial.println("LCD demo complete.");
}

void loop() {
  // Pulse the backlight colour
  static int hue = 0;
  hue += 5;
  if (hue > 360) hue = 0;
  delay(100);
}
